'use strict';
const {escapeHtml:e}=require('./security');
const {getSetting}=require('./db');
const {INSTITUTION:I}=require('./institution');
const brandMark=(label='Emblema do Instituto Superior Maria Mãe de África')=>`<span class="iv4-brandmark" role="img" aria-label="${e(label)}"><img class="iv4-local-mark iv4-single-mark" src="/selo-ismma-referencia.svg" alt="Logótipo ISMMA" width="64" height="72" decoding="async"><span class="iv4-mark-fallback" aria-hidden="true">ISMMA</span></span>`;
const STATUS={aberto:'Aberto',em_analise:'Em análise',aguarda_utilizador:'Aguarda resposta',respondido:'Respondido',fechado:'Fechado'};
const PRIORITY={baixa:'Baixa',normal:'Normal',alta:'Alta'};
const ROLE={administrador:'Administrador',funcionario:'Funcionário',estudante:'Estudante',candidato:'Candidato'};
const VISIBILITY={publico:'Público',estudantes:'Só estudantes',candidatos:'Só candidatos',interno:'Interno'};
function niceDate(s){if(!s)return '—';const d=new Date(String(s).replace(' ','T')+'Z');return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('pt-PT',{timeZone:'Africa/Maputo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d);}
function money(x){return new Intl.NumberFormat('pt-MZ').format(x);}
function statusBadge(s){return `<span class="badge badge-${e(s)}"><span class="badge-dot"></span>${e(STATUS[s]||s)}</span>`;}
function priorityBadge(p){return `<span class="priority priority-${e(p)}">${e(PRIORITY[p]||p)}</span>`;}
function avatar(n){return e(String(n||'U').trim().split(/\s+/).slice(0,2).map(v=>v[0]?.toUpperCase()||'').join(''));}
function icon(name){const shapes={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',inbox:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 13h5l2 3h4l2-3h5"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v1"/>',building:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M9 21v-5h6v5M8 8h1m6 0h1M8 12h1m6 0h1"/>',tag:'<path d="M20 13l-7 7-10-10V3h7z"/><circle cx="7.5" cy="7.5" r="1"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M4.9 4.9 7 7m10 10 2.1 2.1M2 12h3m14 0h3M4.9 19.1 7 17M17 7l2.1-2.1"/>',chart:'<path d="M4 20V12M10 20V5M16 20v-8M22 20V9M2 21h22"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m4 12 5 5L20 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',logout:'<path d="M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h5M15 17l5-5-5-5m5 5H9"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',message:'<path d="M21 11.5a8.4 8.4 0 0 1-8.5 8.5 9 9 0 0 1-4-.9L3 21l2-5.5a9 9 0 0 1-.9-4A8.4 8.4 0 0 1 12.5 3a8.4 8.4 0 0 1 8.5 8.5Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',spark:'<path d="m12 2 2.3 7.7L22 12l-7.7 2.3L12 22l-2.3-7.7L2 12l7.7-2.3z"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',trash:'<path d="M4 7h16M10 11v7m4-7v7M6 7l1 14h10l1-14M9 7V4h6v3"/>',whatsapp:'<path d="M20.5 11.6a8.4 8.4 0 0 1-12.4 7.4L3 20.5l1.5-5a8.4 8.4 0 1 1 16-3.9Z"/><path d="M9 8.3c.2-.5.4-.5.6-.5h.5c.2 0 .4 0 .6.4l.8 1.8c.1.2 0 .4-.1.6l-.6.7c-.1.2-.2.4 0 .7.5.9 1.3 1.7 2.3 2.1.3.1.5.1.7-.1l.7-.8c.2-.2.4-.2.6-.1l1.9.9c.2.1.4.2.4.4 0 .3-.2 1.3-.8 1.9-.6.6-1.4.8-2.3.6-2.1-.4-4.2-2.5-4.6-4.6-.2-.9.1-1.7.6-2.3Z"/>'};return `<svg aria-hidden="true" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${shapes[name]||shapes.grid}</svg>`;}
const helpFab=`<a class="help-fab" href="https://wa.me/258879795209" target="_blank" rel="noopener noreferrer" aria-label="Centro de ajuda ISMMA ATENDE — abrir conversa de WhatsApp">${icon('whatsapp')}<span><b>ISMMA ATENDE</b><small>Centro de ajuda</small></span></a>`;
function csrfField(csrf){return `<input type="hidden" name="_csrf" value="${e(csrf)}">`;}
function button(label,href,kind='primary',extra=''){return `<a class="btn btn-${e(kind)}" href="${e(href)}" ${extra}>${label}</a>`;}
function linkNav(name,href,label,route){return `<a class="nav-link ${route===href||(href!=='/painel'&&route.startsWith(href))?'selected':''}" href="${href}">${icon(name)}<span>${e(label)}</span></a>`;}
function layout({user,title='Painel',subtitle='',content='',route='/',csrf='',unread=0,alert='',error='',institution='Instituto Superior Maria Mãe de África'}){
 const isAdmin=user?.role==='administrador',isStaff=user?.role==='funcionario';
 const academicLinks=(user?.role==='estudante'||user?.is_teacher||isAdmin)?linkNav('file','/academico/disciplinas','Minhas disciplinas',route)+linkNav('clock','/academico/trabalhos','Trabalhos e tarefas',route)+(user?.role==='estudante'?linkNav('chart','/academico/notas','Notas e avaliações',route):''):'';
 const mainLinks=linkNav('grid','/painel','Área pessoal',route)+academicLinks+linkNav('inbox','/pedidos','Pedidos académicos',route)+linkNav('file','/documentos','Documentos',route)+linkNav('bell','/notificacoes','Notificações',route);
 const teamLinks=(isAdmin||isStaff)?linkNav('message','/modelos','Respostas rápidas',route)+(isStaff?linkNav('users','/admin/estudantes','Estudantes confirmados',route):''):'';
 const adminLinks=isAdmin?'<div class="nav-caption">ADMINISTRAÇÃO</div>'+linkNav('users','/admin/utilizadores','Utilizadores',route)+linkNav('building','/admin/departamentos','Departamentos',route)+linkNav('tag','/admin/categorias','Categorias de pedidos',route)+linkNav('users','/admin/estudantes','Registo de estudantes',route)+linkNav('chart','/admin/relatorios','Relatórios',route)+linkNav('clock','/admin/auditoria','Auditoria',route)+linkNav('bell','/admin/notificacoes','Fila de notificações',route)+linkNav('settings','/admin/configuracoes','Configurações',route)+linkNav('users','/admin/candidaturas','Pré-inscrições',route)+linkNav('building','/admin/academico','Gestão académica',route):'';
 const links=`<div class="nav-caption">NAVEGAÇÃO</div>${mainLinks}${teamLinks}${adminLinks}<div class="nav-caption">INSTITUIÇÃO</div>${linkNav('building','/instituicao','Sobre o ISMMA',route)}`;
 const profile=e(user?.is_teacher?'Docente':ROLE[user?.role]||'Utilizador');
 const pageTitle=e(title),name=e(user?.name),logo=brandMark();
 const date=new Intl.DateTimeFormat('pt-MZ',{timeZone:'Africa/Maputo',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date());
 return `<!doctype html><html lang="pt-MZ"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#d39a37"><meta name="description" content="Portal Académico ISMMA, projecto demonstrativo."><title>${pageTitle} | ISMMA</title><link rel="stylesheet" href="/app.css"><link rel="stylesheet" href="/portal-v5.css"><link rel="stylesheet" href="/theme.css"><script src="/app.js" defer></script></head><body class="app-shell m5-app"><a class="skip-link" href="#conteudo">Saltar para o conteúdo</a>
 <aside class="sidebar" id="sidebar"><a class="brand" href="/painel">${logo}<span class="brand-copy"><strong>ISMMA</strong><small>Portal académico</small></span></a><div class="side-label">Ano académico 2026 · Demonstração</div><nav class="navigation" aria-label="Menu da plataforma">${links}</nav><div class="side-bottom"><a href="/perfil" class="side-profile"><span class="avatar">${avatar(user?.name)}</span><span class="user-ident"><strong>${name}</strong><small>${profile}</small></span></a><form method="post" action="/sair">${csrfField(csrf)}<button class="side-logout" type="submit">${icon('logout')} Terminar sessão</button></form></div></aside>
 <div class="main-container"><header class="topbar"><div class="topbar-left"><button class="menu-toggle" type="button" data-menu aria-label="Abrir menu de navegação">${icon('menu')}</button><span class="m5-app-topname">Instituto Superior Maria Mãe de África</span><span class="m5-top-dash">/</span><span class="m5-current-title">${pageTitle}</span></div><div class="topbar-right"><span class="topbar-today">${date}</span><a class="top-notification" href="/notificacoes" aria-label="Notificações">${icon('bell')}${unread?`<b>${unread>9?'9+':unread}</b>`:''}</a><a class="m5-profile-short" href="/perfil"><span class="avatar">${avatar(user?.name)}</span><span class="m5-profile-name">${name}</span><span class="m5-profile-caret" aria-hidden="true">▾</span></a></div></header>
 <main class="page-content" id="conteudo"><nav class="m5-crumbs" aria-label="Caminho"><a href="/painel">Início</a><span aria-hidden="true">›</span><span>${pageTitle}</span></nav><div class="page-heading"><div><h1>${pageTitle}</h1>${subtitle?`<p class="page-subtitle">${e(subtitle)}</p>`:''}</div>${(user?.role==='estudante'||user?.role==='candidato')&&route!=='/pedidos/novo'&&route!=='/perfil'?button(`${icon('plus')} Novo pedido`,'/pedidos/novo'):''}</div>${alert?`<div class="notice" role="status">${icon('check')} ${e(alert)}</div>`:''}${error?`<div class="form-error" role="alert">${e(error)}</div>`:''}${content}</main><footer class="footer"><span>© ${new Date().getFullYear()} ISMMA · Portal académico</span><span>Ambiente de demonstração · Dados fictícios · <a href="/instituicao">Informações institucionais</a></span></footer></div><div class="sidebar-overlay" data-overlay></div>${helpFab}</body></html>`;
}
function publicLayout(title,content){
 return `<!doctype html><html lang="pt-MZ"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#d39a37"><meta name="description" content="Proposta demonstrativa de portal académico e ensino online do ISMMA"><title>${e(title)} | ISMMA</title><link rel="stylesheet" href="/app.css"><link rel="stylesheet" href="/portal-v5.css"><link rel="stylesheet" href="/theme.css"><script src="/app.js" defer></script></head><body class="public-shell m5-public"><a class="skip-link" href="#conteudo">Saltar para o conteúdo</a><div class="m5-toptiny"><div class="m5-container"><span>Portal Académico · Ano lectivo 2026</span><span><a href="https://ismma.ac.mz/site/" rel="noopener noreferrer" target="_blank">Sítio institucional</a> · <a href="mailto:geral@ismma.ac.mz">Contactos</a></span></div></div><header class="m5-header"><div class="m5-container m5-header-wrap"><a class="m5-brand" href="/">${brandMark()}<span><strong>Instituto Superior Maria Mãe de África</strong><small>ISMMA · A Verdade na Caridade</small></span></a><div class="m5-header-actions"><span>Plataforma académica<br><small>Proposta de demonstração</small></span><a class="m5-login-button" href="/entrar">Iniciar sessão ${icon('arrow')}</a></div></div></header><div class="m5-mainnav"><div class="m5-container m5-mainnav-row"><nav class="m5-desktop-nav" aria-label="Menu principal"><a href="/">Página inicial</a><a href="/instituicao">Instituição</a><a href="/instituicao#cursos">Cursos</a><a href="/pre-inscricao">Pré-inscrições</a><a href="/acompanhar-candidatura">Consultar candidatura</a><a href="/documentos">Documentos</a><a href="/entrar">Área reservada</a></nav><button class="iv4-menu-toggle" type="button" aria-expanded="false" aria-controls="iv4-mobile-nav" data-public-menu>${icon('menu')}<span>Menu</span></button></div><nav class="iv4-mobile-nav" id="iv4-mobile-nav" aria-label="Menu para telemóveis" hidden><a href="/">Página inicial</a><a href="/instituicao">A instituição</a><a href="/instituicao#cursos">Cursos</a><a href="/pre-inscricao">Pré-inscrições</a><a href="/acompanhar-candidatura">Consultar candidatura</a><a href="/documentos">Documentos</a><a href="/entrar">Iniciar sessão</a></nav></div><main class="m5-main" id="conteudo">${content}</main><footer class="m5-footer"><div class="m5-container m5-footer-grid"><div><strong>Instituto Superior Maria Mãe de África</strong><p>Av. Vladimir Lenine, n.º 3621<br>Maputo, Moçambique</p><small>A Verdade na Caridade</small></div><div><strong>Serviços académicos</strong><a href="/pre-inscricao">Pré-inscrições</a><a href="/acompanhar-candidatura">Estado da candidatura</a><a href="/entrar">Portal académico</a></div><div><strong>Contactos oficiais</strong><a href="tel:+258826253616">+258 82 625 3616</a><a href="mailto:geral@ismma.ac.mz">geral@ismma.ac.mz</a><a href="https://ismma.ac.mz/site/" target="_blank" rel="noopener noreferrer">ismma.ac.mz</a></div></div><div class="m5-container m5-copyright">© ${new Date().getFullYear()} ISMMA · Proposta independente para demonstração, não constitui um serviço oficial.</div></footer>${helpFab}</body></html>`;
}
function landing(){return publicLayout('Bem-vindo',`<div class="landing"><div class="landing-top"><span class="kicker"><span class="live-dot"></span> PLATAFORMA DE ATENDIMENTO ACADÉMICO</span><h1>O seu pedido, a nossa <em>prioridade.</em></h1><p>Um espaço para estudantes e candidatos comunicarem com os departamentos, acompanharem pedidos e acederem a documentos.</p><p class="landing-institution">${e(I.motto)} · <a href="/instituicao">Conhecer a instituição</a></p><div class="hero-actions">${button('Entrar no portal '+icon('arrow'),'/entrar')}${button('Criar conta','/registar','white')}</div><div class="hero-footnote">${icon('shield')} Versão de demonstração. Não introduza dados pessoais reais.</div></div><div class="hero-visual"><div class="hero-pattern"></div><div class="hero-card"><div class="hero-card-top"><span class="hero-symbol">${icon('inbox')}</span><span class="badge badge-respondido">Acompanhamento do seu pedido</span></div><div class="hero-card-heading">Tudo num só lugar.</div><div class="hero-timeline"><div><b class="line-circle">1</b><span><strong>Crie o seu pedido</strong><small>Escolha o departamento e descreva a situação.</small></span></div><div><b class="line-circle">2</b><span><strong>Acompanhe o estado</strong><small>Consulte mensagens e actualizações.</small></span></div><div><b class="line-circle">3</b><span><strong>Receba a resposta</strong><small>Comunicação clara, sem deslocações desnecessárias.</small></span></div></div></div></div></div><section class="landing-features"><div><span class="feature-icon">${icon('message')}</span><h3>Pedidos e respostas</h3><p>Converse directamente com o departamento responsável.</p></div><div><span class="feature-icon">${icon('file')}</span><h3>Documentos úteis</h3><p>Encontre formulários, editais e informações académicas.</p></div><div><span class="feature-icon">${icon('clock')}</span><h3>Sem perder o acompanhamento</h3><p>Consulte o histórico do seu atendimento a qualquer momento.</p></div></section>`);}
function authForm(kind,csrf,error=''){
 const signup=kind==='registar'; const disabled='';
 return publicLayout(signup?'Criar conta':'Iniciar sessão',`<div class="auth-bg"><div class="auth-card"><div class="auth-title"><div class="auth-emblem">${icon('spark')}</div><h1>${signup?'Crie a sua conta':'Iniciar sessão'}</h1><p>${signup?'Crie uma conta de demonstração para acesso aos serviços do portal.':'Entre para consultar disciplinas, trabalhos, notas e serviços académicos.'}</p></div>${error?`<div class="form-error" role="alert">${e(error)}</div>`:''}<form method="post" action="/${signup?'registar':'entrar'}" class="form-stack">${csrfField(csrf)}${signup?`<label>Tipo de conta<select name="role" required data-role-select><option value="estudante">Estudante interno</option><option value="candidato">Candidato</option></select></label><label>Nome completo<input name="name" autocomplete="name" required maxlength="120" placeholder="Ex.: Ana Macuácua"></label><label>Telefone<input name="phone" autocomplete="tel" placeholder="Ex.: 84 123 4567" required maxlength="30"></label><div data-student-fields><label>Número de estudante<input name="student_number" maxlength="40" placeholder="Ex.: ISMMA2026001"></label><label>Curso frequentado<input name="course" maxlength="120" placeholder="Ex.: Licenciatura em Gestão de Empresas" list="cursos-ismma"></label></div><div data-candidate-fields hidden><label>Curso pretendido<input name="desired_course" maxlength="120" placeholder="Ex.: Licenciatura em Contabilidade e Auditoria" list="cursos-ismma"></label></div>`:''}<datalist id="cursos-ismma">${I.courses.map(course=>`<option value="${e(course)}"></option>`).join('')}</datalist><label>Email<input name="email" type="email" required autocomplete="email" maxlength="180" placeholder="seuemail@exemplo.com"></label><label>Palavra-passe<input name="password" type="password" required autocomplete="${signup?'new-password':'current-password'}" ${signup?'minlength="10"':''} placeholder="${signup?'Mínimo de 10 caracteres':'Introduza a sua palavra-passe'}"></label>${signup?`<p class="hint">Use pelo menos 10 caracteres, com uma letra maiúscula, uma minúscula e um número.</p>`:''}<button type="submit" class="btn btn-primary btn-full">${signup?'Criar conta':'Entrar no portal'} ${icon('arrow')}</button></form><p class="auth-switch">${signup?'Já tem uma conta? <a href="/entrar">Iniciar sessão</a>':'Ainda não tem conta? <a href="/registar">Criar conta</a> · <a href="/recuperar">Esqueceu-se da palavra-passe?</a>'}</p></div><aside class="auth-side"><span class="kicker">INSTITUTO SUPERIOR MARIA MÃE DE ÁFRICA</span><h2>Mais perto de si.<br>Onde quer que esteja.</h2><p>Informação académica acessível, segura e organizada.</p><div class="auth-decor"><span>${icon('check')} Atendimentos centralizados</span><span>${icon('check')} Comunicação transparente</span><span>${icon('check')} Documentos disponíveis</span></div></aside></div>`);
}
function statCard(title,value,ico,color='blue',description=''){return `<div class="stat-card"><span class="stat-icon tone-${e(color)}">${icon(ico)}</span><span class="stat-label">${e(title)}</span><strong class="stat-value">${money(value)}</strong><span class="stat-desc">${e(description)}</span></div>`;}
function ticketTable(rows){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>PROTOCOLO</th><th>ASSUNTO</th><th>DEPARTAMENTO</th><th>ESTADO</th><th>DATA</th><th></th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr><td><a class="protocol" href="/pedidos/${t.id}">${e(t.protocol)}</a></td><td><div class="table-primary">${e(t.subject)}</div>${t.owner_name?`<small>${e(t.owner_name)}</small>`:''}</td><td>${e(t.department_name)}</td><td>${statusBadge(t.status)}${t.sla_hours&&['aberto','em_analise','aguarda_utilizador'].includes(t.status)&& (Date.now()-Date.parse(t.created_at.replace(' ','T')+'Z'))>t.sla_hours*3600000?' <small class="badge badge-alta">Em atraso</small>':''}</td><td class="date-cell">${niceDate(t.created_at)}</td><td><a class="table-arrow" href="/pedidos/${t.id}" aria-label="Abrir pedido">${icon('arrow')}</a></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty-state">${icon('inbox')}<strong>Nenhum pedido encontrado</strong><span>Experimente outros filtros ou crie um novo pedido.</span></div></td></tr>`}</tbody></table></div>`;}
function dashboard({user,stats,recent,departments}){
  const staff=['administrador','funcionario'].includes(user.role);let subtitle=staff?'Veja o que precisa da atenção da sua equipa.':'Acompanhe os seus pedidos e mantenha-se informado.';
  return `<div class="welcome-banner"><div><span>PORTAL DE ATENDIMENTO ISMMA</span><h2>Olá, ${e(user.name.split(' ')[0])}.</h2><p>${e(subtitle)}</p>${!staff?button(`Fazer novo pedido ${icon('arrow')}`,'/pedidos/novo','white'):button(`Ver todos os pedidos ${icon('arrow')}`,'/pedidos','white')}</div><div class="welcome-art"><span class="circle-one"></span><span class="circle-two"></span>${icon('spark')}</div></div><div class="stats-grid">${statCard('Total de pedidos',stats.total,'inbox','blue','Todos os registos')}${statCard('Em aberto / análise',stats.pending,'clock','amber','Aguardam acompanhamento')}${statCard('Respondidos',stats.answered,'check','green','Com resposta disponível')}${statCard('Fechados',stats.closed,'file','purple','Atendimentos concluídos')}</div><div class="dashboard-two"><section class="panel"><div class="panel-head"><div><h2>Pedidos recentes</h2><p>Acompanhe as últimas actualizações.</p></div>${button('Ver todos '+icon('arrow'),'/pedidos','subtle')}</div>${ticketTable(recent)}</section><aside class="panel quick-panel"><div class="panel-head"><div><h2>Acesso rápido</h2><p>O que pretende fazer?</p></div></div><a class="quick-link" href="${staff?'/pedidos':'/pedidos/novo'}"><span class="quick-icon blue">${icon('inbox')}</span><span><strong>${staff?'Gerir pedidos':'Criar pedido'}</strong><small>${staff?'Responder e encaminhar':'Contactar um departamento'}</small></span>${icon('arrow')}</a><a class="quick-link" href="/documentos"><span class="quick-icon green">${icon('file')}</span><span><strong>Biblioteca de documentos</strong><small>Consulte documentos disponíveis</small></span>${icon('arrow')}</a><a class="quick-link" href="/notificacoes"><span class="quick-icon purple">${icon('bell')}</span><span><strong>Notificações</strong><small>Actualizações do atendimento</small></span>${icon('arrow')}</a>${staff?`<div class="quick-note">${icon('building')} ${departments.length} departamento(s) sob a sua gestão.</div>`:''}</aside></div>`;
}
function ticketList({rows,filters,departments,page,total}){
 const opts=[['','Todos os estados'],...Object.entries(STATUS)].map(([v,l])=>`<option value="${e(v)}" ${filters.estado===v?'selected':''}>${e(l)}</option>`).join('');
 const depOpts=`<option value="">Todos os departamentos</option>`+departments.map(d=>`<option value="${d.id}" ${Number(filters.departamento)===d.id?'selected':''}>${e(d.name)}</option>`).join('');
 const totalPages=Math.ceil(total/12);
 return `<section class="panel"><div class="panel-head"><div><h2>Consultar pedidos</h2><p>${total} pedido(s) encontrado(s).</p></div></div><form class="filter-bar" method="get" action="/pedidos"><label class="search-field">${icon('search')}<input name="pesquisa" value="${e(filters.pesquisa||'')}" placeholder="Protocolo, assunto ou utilizador" aria-label="Pesquisar"></label><select name="estado" aria-label="Estado">${opts}</select><select name="departamento" aria-label="Departamento">${depOpts}</select><button class="btn btn-primary" type="submit">Filtrar</button></form>${ticketTable(rows)}${totalPages>1?`<div class="pager"><span>Página ${page} de ${totalPages}</span><div>${page>1?button('Anterior',`/pedidos?${new URLSearchParams({...filters,pagina:page-1}).toString()}`,'subtle'):''}${page<totalPages?button('Seguinte',`/pedidos?${new URLSearchParams({...filters,pagina:page+1}).toString()}`,'subtle'):''}</div></div>`:''}</section>`;
}
function newTicket({csrf,departments,categories,error=''}){return `<div class="form-layout"><section class="panel form-panel"><div class="panel-head"><div><h2>Detalhes do pedido</h2><p>Preencha os campos abaixo para enviar o seu pedido.</p></div></div>${error?`<div class="form-error">${e(error)}</div>`:''}<form method="post" action="/pedidos" enctype="multipart/form-data" class="form-stack">${csrfField(csrf)}<div class="form-grid"><label>Departamento <span class="required">*</span><select name="department_id" data-department required><option value="">Seleccione o departamento</option>${departments.map(d=>`<option value="${d.id}">${e(d.name)}</option>`).join('')}</select></label><label>Categoria <span class="required">*</span><select name="category_id" data-category required><option value="">Seleccione primeiro o departamento</option>${categories.map(c=>`<option data-department-id="${c.department_id}" value="${c.id}" hidden>${e(c.name)}</option>`).join('')}</select></label></div><label>Assunto <span class="required">*</span><input name="subject" required minlength="5" maxlength="160" placeholder="Ex.: Informação sobre matrícula"></label><label>Descrição do pedido <span class="required">*</span><textarea name="description" required minlength="10" maxlength="5000" rows="7" placeholder="Explique o que precisa de saber. Quanto mais clara a descrição, melhor poderemos ajudar."></textarea></label><div class="upload-box"><span class="upload-ico">${icon('file')}</span><div><strong>Adicionar anexos <span>(opcional)</span></strong><p>PDF, Word, JPG ou PNG · Até 5 ficheiros de 5 MB cada.</p></div><input type="file" name="anexos" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png" multiple aria-label="Anexar ficheiros"></div><div class="form-actions"><a class="btn btn-subtle" href="/pedidos">Cancelar</a><button class="btn btn-primary" type="submit">Submeter pedido ${icon('arrow')}</button></div></form></section><aside class="helper-card"><span class="helper-icon">${icon('shield')}</span><h3>Antes de submeter</h3><p>O seu pedido recebe um número de protocolo e fica disponível na plataforma.</p><ul><li>Escolha o departamento certo.</li><li>Descreva a situação com clareza.</li><li>Evite enviar dados sensíveis desnecessários.</li><li>Consulte as respostas no painel.</li></ul></aside></div>`;}
function ticketDetail({user,ticket,messages,attachments,histories,departments,staff,templates,csrf,reopenDays}){
 const owner=ticket.user_id===user.id;const canRespond=ticket.status!=='fechado'&&!(owner&&ticket.status==='respondido');const canReopen=owner&&ticket.status==='respondido' && (Date.now()-new Date(ticket.updated_at.replace(' ','T')+'Z').getTime())/(86400000)<=reopenDays;
 const byMessage={};for(const a of attachments){const key=a.message_id||'initial';(byMessage[key]??=[]).push(a);}
 const attachmentsList=arr=>arr?.length?`<div class="attachment-list">${arr.map(a=>`<a class="attachment" href="/anexos/${a.id}">${icon('download')} ${e(a.original_name)} <small>${(a.size/1024).toFixed(0)} KB</small></a>`).join('')}</div>`:'';
 return `<div class="detail-top"><a href="/pedidos" class="backlink">← Voltar aos pedidos</a><div class="ticket-heading"><div><p class="protocol">${e(ticket.protocol)}</p><h2>${e(ticket.subject)}</h2><p>Enviado por ${e(ticket.owner_name)} · ${niceDate(ticket.created_at)}</p></div>${statusBadge(ticket.status)}</div></div><div class="ticket-layout"><div class="ticket-main"><section class="panel conversation"><div class="panel-head"><div><h2>Conversa</h2><p>Histórico de comunicação deste pedido.</p></div></div><div class="conversation-body"><div class="message-item"><div class="avatar avatar-outline">${avatar(ticket.owner_name)}</div><div class="message-content"><div class="message-meta"><strong>${e(ticket.owner_name)}</strong><span>${niceDate(ticket.created_at)}</span></div><div class="message-bubble">${e(ticket.description).replace(/\n/g,'<br>')}</div>${attachmentsList(byMessage.initial)}</div></div>${messages.map(m=>`<div class="message-item ${m.is_internal?'internal-message':''}"><div class="avatar ${m.user_id===user.id?'avatar-self':'avatar-outline'}">${avatar(m.name)}</div><div class="message-content"><div class="message-meta"><strong>${e(m.name)}</strong>${m.is_internal?'<span class="internal-label">Nota interna</span>':''}<span>${niceDate(m.created_at)}</span></div><div class="message-bubble">${e(m.body).replace(/\n/g,'<br>')}</div>${attachmentsList(byMessage[m.id])}</div></div>`).join('')}</div>${canRespond?`<div class="reply-box"><form method="post" action="/pedidos/${ticket.id}/mensagem" enctype="multipart/form-data" class="form-stack">${csrfField(csrf)}<label>Escrever resposta ${staff&&templates.length?`<select class="template-select" data-template><option value="">Utilizar resposta rápida</option>${templates.map(t=>`<option data-body="${e(t.body)}" value="${t.id}">${e(t.title)}</option>`).join('')}</select>`:''}<textarea name="body" rows="4" minlength="2" maxlength="5000" required placeholder="Escreva a sua mensagem..." data-reply-textarea></textarea></label><div class="reply-bottom"><label class="file-inline">${icon('file')} Anexar ficheiros <input type="file" name="anexos" multiple accept=".pdf,.doc,.docx,.jpg,.jpeg,.png"></label>${staff?`<label class="inline-check"><input type="checkbox" name="is_internal" value="1"> Nota interna</label>`:''}<button type="submit" class="btn btn-primary">Enviar resposta ${icon('arrow')}</button></div></form></div>`:canReopen?`<div class="reply-box"><form method="post" action="/pedidos/${ticket.id}/reabrir">${csrfField(csrf)}<p>Este pedido foi respondido. Precisa de mais esclarecimentos?</p><button class="btn btn-primary" type="submit">Reabrir pedido</button></form></div>`:'<div class="reply-box"><p class="muted">Este pedido está fechado. Não é possível enviar novas mensagens.</p></div>'}</section><section class="panel timeline-panel"><div class="panel-head"><h2>Histórico do pedido</h2></div><div class="timeline-list">${histories.map(h=>`<div class="history-row"><span class="history-dot"></span><div><strong>${e(h.action.replace(/_/g,' '))}</strong><p>${e(h.from_value||'')}${h.from_value?' → ':''}${e(h.to_value||'')}</p></div><time>${niceDate(h.created_at)}</time></div>`).join('')}</div></section></div><aside class="ticket-side"><section class="panel side-info"><h3>Informações do pedido</h3><dl><dt>Departamento</dt><dd>${e(ticket.department_name)}</dd><dt>Categoria</dt><dd>${e(ticket.category_name||'Geral')}</dd><dt>Prioridade</dt><dd>${priorityBadge(ticket.priority)}</dd><dt>Estado</dt><dd>${statusBadge(ticket.status)}</dd><dt>Data de abertura</dt><dd>${niceDate(ticket.created_at)}</dd><dt>Última actualização</dt><dd>${niceDate(ticket.updated_at)}</dd></dl></section>${staff?`<section class="panel side-actions"><h3>Gerir atendimento</h3><form method="post" action="/pedidos/${ticket.id}/estado" class="form-stack">${csrfField(csrf)}<label>Estado<select name="status">${Object.entries(STATUS).map(([v,l])=>`<option value="${v}" ${ticket.status===v?'selected':''}>${e(l)}</option>`).join('')}</select></label><label>Prioridade<select name="priority">${Object.entries(PRIORITY).map(([v,l])=>`<option value="${v}" ${ticket.priority===v?'selected':''}>${e(l)}</option>`).join('')}</select></label><button class="btn btn-subtle btn-full" type="submit">Actualizar pedido</button></form><hr><form method="post" action="/pedidos/${ticket.id}/encaminhar" class="form-stack">${csrfField(csrf)}<label>Encaminhar para<select name="department_id">${departments.map(d=>`<option value="${d.id}" ${d.id===ticket.department_id?'selected':''}>${e(d.name)}</option>`).join('')}</select></label><button class="btn btn-subtle btn-full" type="submit">Encaminhar</button></form></section>`:''}</aside></div>`;
}
function documentPage({documents,departments,canManage,csrf,trash=false}){
  const cards=documents.map(d=>`<article class="document-card"><span class="document-symbol">${icon('file')}</span><div><span class="document-cat">${e(d.category)} · ${e(VISIBILITY[d.visibility])}</span><h3>${e(d.title)}</h3><p>${e(d.description||'Documento disponibilizado pelo ISMMA.')}</p><div class="document-meta">${e(d.department_name||'ISMMA')} · ${niceDate(d.published_at)} · ${(d.size/1024).toFixed(0)} KB</div><div class="doc-actions">${!d.deleted_at?button(`${icon('download')} Descarregar`,`/documentos/${d.id}/descarregar`,'subtle'):''}${d.can_manage?`<a class="btn btn-subtle" href="/documentos/${d.id}/versoes">Versões</a><form method="post" action="/documentos/${d.id}/${d.deleted_at?'recuperar':'remover'}">${csrfField(csrf)}<button class="btn btn-text" type="submit">${d.deleted_at?'Recuperar':'Remover'}</button></form>`:''}</div>${d.can_manage&&!d.deleted_at?`<form method="post" action="/documentos/${d.id}/substituir" enctype="multipart/form-data" class="replace-form">${csrfField(csrf)}<input name="documento" type="file" accept=".pdf,.doc,.docx" required aria-label="Ficheiro de substituição"><button type="submit" class="btn btn-small btn-subtle">Substituir ficheiro</button></form>`:''}</div></article>`).join('');
 return `${canManage?`<section class="panel form-panel documents-upload"><div class="panel-head"><div><h2>Publicar documento</h2><p>Disponibilize formulários, editais e regulamentos.</p></div></div><form method="post" action="/documentos" enctype="multipart/form-data" class="form-stack">${csrfField(csrf)}<div class="form-grid"><label>Título<input name="title" required maxlength="150" placeholder="Ex.: Calendário académico"></label><label>Categoria<input name="category" required maxlength="80" placeholder="Ex.: Editais"></label><label>Departamento<select name="department_id"><option value="">Institucional / geral</option>${departments.map(d=>`<option value="${d.id}">${e(d.name)}</option>`).join('')}</select></label><label>Válido até (opcional)<input name="valid_until" type="date"></label><label>Visibilidade<select name="visibility">${Object.entries(VISIBILITY).map(([v,l])=>`<option value="${v}">${e(l)}</option>`).join('')}</select></label></div><label>Descrição<input name="description" maxlength="600" placeholder="Breve descrição (opcional)"></label><label>Ficheiro PDF ou Word<input type="file" name="documento" accept=".pdf,.doc,.docx" required></label><button class="btn btn-primary" type="submit">${icon('plus')} Publicar documento</button></form></section>`:''}<section class="panel"><div class="panel-head"><div><h2>${trash?'Documentos removidos':'Biblioteca de documentos'}</h2><p>Consulte os ficheiros disponíveis para o seu perfil.</p></div>${canManage?button(trash?'Voltar à biblioteca':'Documentos removidos',trash?'/documentos':'/documentos?removidos=1','subtle'):''}</div><div class="documents-grid">${cards||'<div class="empty-state">Ainda não existem documentos nesta categoria.</div>'}</div></section>`;
}
function notificationPage({items,csrf}){return `<section class="panel"><div class="panel-head"><div><h2>Centro de notificações</h2><p>Informações importantes sobre os seus pedidos.</p></div><form method="post" action="/notificacoes/lidas">${csrfField(csrf)}<button class="btn btn-subtle" type="submit">Marcar todas como lidas</button></form></div><div class="notification-list">${items.length?items.map(n=>`<a href="/notificacoes/${n.id}/abrir" class="notification-row ${n.read_at?'':'unread'}"><span class="notification-ico">${icon('bell')}</span><span><strong>${e(n.title)}</strong><p>${e(n.body)}</p><small>${niceDate(n.created_at)}</small></span>${n.read_at?'':'<i class="unread-dot"></i>'}</a>`).join(''):'<div class="empty-state">Ainda não existem notificações.</div>'}</div></section>`;}
function profile({user,csrf}){return `<section class="panel profile-panel"><div class="profile-header"><span class="profile-big-avatar">${avatar(user.name)}</span><div><h2>${e(user.name)}</h2><p>${e(ROLE[user.role])} · ${e(user.email)}</p></div></div><form method="post" action="/perfil" class="form-stack">${csrfField(csrf)}<div class="form-grid"><label>Nome completo<input name="name" maxlength="120" required value="${e(user.name)}"></label><label>Telefone<input name="phone" maxlength="30" required value="${e(user.phone)}"></label></div><label>Email (não editável)<input disabled value="${e(user.email)}"></label><hr><h3>Alterar palavra-passe</h3><p class="hint">Deixe estes campos em branco para manter a palavra-passe actual.</p><div class="form-grid"><label>Palavra-passe actual<input name="current_password" type="password"></label><label>Nova palavra-passe<input name="new_password" type="password"></label></div><button class="btn btn-primary" type="submit">Guardar alterações</button></form></section>`;}
function administrationTable(headers,rows,empty='Nenhum registo encontrado.'){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}"><div class="empty-state">${e(empty)}</div></td></tr>`}</tbody></table></div>`;}
function usersAdmin({users,departments,csrf}){
  return `<section class="panel form-panel"><div class="panel-head"><h2>Criar utilizador</h2></div><form method="post" action="/admin/utilizadores" class="form-stack">${csrfField(csrf)}<div class="form-grid form-grid-three"><label>Nome<input name="name" maxlength="120" required></label><label>Email<input name="email" type="email" required></label><label>Telefone<input name="phone" maxlength="30" required></label><label>Perfil<select name="role">${Object.entries(ROLE).map(([r,n])=>`<option value="${r}">${e(n)}</option>`).join('')}</select></label><label>Palavra-passe<input name="password" type="password" required minlength="10" placeholder="Ex.: Segura12345"></label><label>Número de estudante<input name="student_number" maxlength="40"></label><label>Curso<input name="course" maxlength="120"></label><label>Curso pretendido<input name="desired_course" maxlength="120"></label><label>Departamento(s) do funcionário<select name="departments" multiple size="3" title="Use Ctrl para seleccionar vários">${departments.map(d=>`<option value="${d.id}">${e(d.name)}</option>`).join('')}</select></label></div><button class="btn btn-primary" type="submit">${icon('plus')} Criar utilizador</button></form></section><section class="panel"><div class="panel-head"><h2>Contas de utilizadores</h2><p>${users.length} registos</p></div>${administrationTable(['UTILIZADOR','PERFIL','DEPARTAMENTO(S)','ESTADO','ACÇÕES'],users.map(u=>`<tr><td><div class="table-primary">${e(u.name)}</div><small>${e(u.email)}</small></td><td>${e(ROLE[u.role])}</td><td>${e(u.departments||'—')}</td><td>${u.is_active?'<span class="ok-text">Activo</span>':'<span class="danger-text">Bloqueado</span>'}</td><td><div class="actions-inline"><a class="btn btn-small btn-subtle" href="/admin/utilizadores/${u.id}">Editar</a><form method="post" action="/admin/utilizadores/${u.id}/estado">${csrfField(csrf)}<button class="btn btn-small btn-text" type="submit">${u.is_active?'Bloquear':'Activar'}</button></form></div></td></tr>`))}</section>`;
}
function userEdit({record,departments,csrf}){const deps=record.department_ids||[];return `<section class="panel form-panel"><div class="panel-head"><h2>Editar utilizador</h2></div><form method="post" action="/admin/utilizadores/${record.id}/guardar" class="form-stack">${csrfField(csrf)}<div class="form-grid"><label>Nome<input name="name" required value="${e(record.name)}"></label><label>Email<input name="email" type="email" required value="${e(record.email)}"></label><label>Telefone<input name="phone" required value="${e(record.phone)}"></label><label>Perfil<select name="role">${Object.entries(ROLE).map(([r,l])=>`<option value="${r}" ${record.role===r?'selected':''}>${e(l)}</option>`).join('')}</select></label><label>Número de estudante<input name="student_number" value="${e(record.student_number)}"></label><label>Curso<input name="course" value="${e(record.course)}"></label><label>Curso pretendido<input name="desired_course" value="${e(record.desired_course)}"></label><label>Nova palavra-passe (opcional)<input name="password" type="password" minlength="10"></label><label>Departamento(s) do funcionário<select name="departments" multiple size="5">${departments.map(d=>`<option value="${d.id}" ${deps.includes(d.id)?'selected':''}>${e(d.name)}</option>`).join('')}</select></label></div><button type="submit" class="btn btn-primary">Guardar utilizador</button></form></section>`;}
function departmentsAdmin({departments,csrf}){return `<section class="panel form-panel"><div class="panel-head"><h2>Novo departamento</h2></div><form method="post" action="/admin/departamentos" class="form-stack">${csrfField(csrf)}<div class="form-grid"><label>Nome<input name="name" required maxlength="90" placeholder="Ex.: Recursos Humanos"></label><label>Email institucional<input name="email" type="email" placeholder="departamento@ismma.ac.mz"></label></div><label>Descrição<input name="description" maxlength="500"></label><button type="submit" class="btn btn-primary">${icon('plus')} Criar departamento</button></form></section><section class="panel"><div class="panel-head"><h2>Departamentos</h2></div><div class="admin-card-grid">${departments.map(d=>`<article class="admin-item"><div class="admin-item-head"><span class="admin-icon">${icon('building')}</span><strong>${e(d.name)}</strong><span class="${d.is_active?'ok-text':'danger-text'}">${d.is_active?'Activo':'Inactivo'}</span></div><form method="post" action="/admin/departamentos/${d.id}/guardar" class="form-stack">${csrfField(csrf)}<label>Nome<input name="name" value="${e(d.name)}" required></label><label>Email<input name="email" type="email" value="${e(d.email)}"></label><label>Descrição<input name="description" value="${e(d.description)}"></label><button class="btn btn-subtle" type="submit">Guardar</button></form><div class="actions-inline"><form method="post" action="/admin/departamentos/${d.id}/estado">${csrfField(csrf)}<button class="btn btn-text" type="submit">${d.is_active?'Desactivar':'Activar'}</button></form><form method="post" action="/admin/departamentos/${d.id}/apagar" data-confirm="Remover este departamento? Só será possível se não tiver pedidos associados.">${csrfField(csrf)}<button class="btn btn-text danger-text" type="submit">Remover</button></form></div></article>`).join('')}</div></section>`;}
function categoriesAdmin({categories,departments,csrf}){return `<section class="panel form-panel"><div class="panel-head"><h2>Nova categoria</h2></div><form method="post" action="/admin/categorias" class="form-stack">${csrfField(csrf)}<div class="form-grid form-grid-three"><label>Departamento<select name="department_id" required>${departments.map(d=>`<option value="${d.id}">${e(d.name)}</option>`).join('')}</select></label><label>Nome<input name="name" maxlength="90" required></label><label>Prazo de atendimento (horas)<input type="number" name="sla_hours" min="1" max="2160" value="72" required></label><label>Destinatários<select name="applies_to"><option value="ambos">Ambos</option><option value="estudante">Estudantes</option><option value="candidato">Candidatos</option></select></label></div><button type="submit" class="btn btn-primary">${icon('plus')} Criar categoria</button></form></section><section class="panel"><div class="panel-head"><h2>Categorias de atendimento</h2></div>${administrationTable(['CATEGORIA','DEPARTAMENTO','TIPO','ESTADO','ACÇÕES'],categories.map(c=>`<tr><td class="table-primary">${e(c.name)}</td><td>${e(c.department_name)}</td><td>${e(c.applies_to)}</td><td>${c.is_active?'Activa':'Inactiva'} · ${c.sla_hours||'Padrão'} h</td><td class="table-actions"><form method="post" action="/admin/categorias/${c.id}/prazo">${csrfField(csrf)}<input type="number" name="sla_hours" min="1" max="2160" value="${c.sla_hours||72}" aria-label="Prazo em horas" required><button class="btn btn-small btn-subtle">Guardar prazo</button></form><form method="post" action="/admin/categorias/${c.id}/estado">${csrfField(csrf)}<button class="btn btn-small btn-subtle" type="submit">${c.is_active?'Desactivar':'Activar'}</button></form></td></tr>`))}</section>`;}
function templatesPage({templates,departments,csrf}){return `<section class="panel form-panel"><div class="panel-head"><h2>Criar resposta rápida</h2></div><form method="post" action="/modelos" class="form-stack">${csrfField(csrf)}<div class="form-grid"><label>Departamento<select name="department_id" required>${departments.map(d=>`<option value="${d.id}">${e(d.name)}</option>`).join('')}</select></label><label>Título<input name="title" required maxlength="120" placeholder="Ex.: Pedido recebido"></label></div><label>Texto da resposta<textarea name="body" rows="4" required maxlength="4000"></textarea></label><button class="btn btn-primary" type="submit">Guardar modelo</button></form></section><section class="panel"><div class="panel-head"><h2>Modelos de resposta</h2></div><div class="template-list">${templates.map(t=>`<div class="template-item"><div><strong>${e(t.title)}</strong><small>${e(t.department_name)}</small><p>${e(t.body)}</p></div><form method="post" action="/modelos/${t.id}/apagar" data-confirm="Remover modelo?">${csrfField(csrf)}<button class="btn btn-text" type="submit">${icon('trash')} Remover</button></form></div>`).join('')||'<div class="empty-state">Nenhum modelo disponível.</div>'}</div></section>`;}
function settingsAdmin({settings,csrf}){return `<section class="panel form-panel settings-panel"><div class="panel-head"><div><h2>Definições do portal</h2><p>Configurações institucionais e limites de atendimento.</p></div></div><form method="post" action="/admin/configuracoes" class="form-stack">${csrfField(csrf)}<div class="form-grid"><label>Nome da instituição<input name="institution_name" value="${e(settings.institution_name)}" required></label><label>Email de contacto<input type="email" name="contact_email" value="${e(settings.contact_email)}" required></label><label>Dias para reabrir pedido<input type="number" min="1" max="90" name="reopen_days" value="${e(settings.reopen_days)}" required></label><label>Dias até pedido em atraso<input type="number" min="1" max="90" name="overdue_days" value="${e(settings.overdue_days)}" required></label><label>Tamanho máximo de documento (MB)<input type="number" min="1" max="20" name="max_document_mb" value="${e(settings.max_document_mb)}" required></label><label>Exibir nome do funcionário nas respostas<select name="show_staff_name"><option value="0" ${settings.show_staff_name!=='1'?'selected':''}>Não</option><option value="1" ${settings.show_staff_name==='1'?'selected':''}>Sim</option></select></label></div><button class="btn btn-primary" type="submit">Guardar configurações</button></form></section>`;}
function reportsPage({totals,byDep,byStatus,active,overdue,avg,range}){return `<div class="report-actions"><a class="btn btn-primary" href="/admin/relatorios.csv?inicio=${e(range.inicio||'')}&fim=${e(range.fim||'')}">${icon('download')} Exportar CSV</a><button class="btn btn-subtle" type="button" data-print>Imprimir / Guardar PDF</button></div><form class="filter-bar report-filters" action="/admin/relatorios" method="get"><label>Data inicial<input name="inicio" type="date" value="${e(range.inicio||'')}"></label><label>Data final<input name="fim" type="date" value="${e(range.fim||'')}"></label><button type="submit" class="btn btn-primary">Aplicar</button></form><div class="stats-grid">${statCard('Pedidos no período',totals,'inbox','blue')}${statCard('Em atraso',overdue,'clock','amber')}${statCard('Tempo médio até resposta (h)',avg,'chart','green')}${statCard('Utilizadores activos',active,'users','purple')}</div><div class="dashboard-two"><section class="panel"><div class="panel-head"><h2>Pedidos por departamento</h2></div>${administrationTable(['DEPARTAMENTO','PEDIDOS'],byDep.map(r=>`<tr><td>${e(r.name)}</td><td>${r.count}</td></tr>`))}</section><section class="panel"><div class="panel-head"><h2>Pedidos por estado</h2></div>${administrationTable(['ESTADO','PEDIDOS'],byStatus.map(r=>`<tr><td>${statusBadge(r.status)}</td><td>${r.count}</td></tr>`))}</section></div>`;}
function auditPage({logs}){return `<section class="panel"><div class="panel-head"><h2>Registo de actividades</h2><p>Últimos 100 eventos do sistema.</p></div>${administrationTable(['DATA','UTILIZADOR','ACÇÃO','REFERÊNCIA','DETALHES'],logs.map(l=>`<tr><td>${niceDate(l.created_at)}</td><td>${e(l.name||'Sistema')}</td><td>${e(l.action)}</td><td>${e(l.subject_type)} #${e(l.subject_id||'—')}</td><td>${e(l.details||'')}</td></tr>`))}</section>`;}
function errorPage(code,message,user=null){const body=`<div class="error-page"><div class="error-code">${e(code)}</div><h1>${e(message)}</h1><p>Regresse ao portal e tente novamente.</p>${button('Voltar ao portal',user?'/painel':'/')}</div>`;return publicLayout('Erro',body);}

function studentRosterPage({rows=[],csrf,query='',preview=null}){
 const table=rows.length?administrationTable(['NÚMERO','ESTUDANTE','CURSO','ESTADO','ACÇÃO'],rows.map(x=>`<tr><td>${e(x.student_number)}</td><td>${e(x.name)}</td><td>${e(x.course)}</td><td>${e(x.status)}</td><td><form method="post" action="/admin/estudantes/${x.id}/estado">${csrfField(csrf)}<button class="btn btn-subtle" type="submit">${x.status==='activo'?'Desactivar':'Activar'}</button></form></td></tr>`)):'<p class="muted">Ainda não existem registos para apresentar.</p>';
 return `<section class="panel form-panel"><div class="panel-head"><div><h2>Importar estudantes</h2><p>CSV com colunas: numero,nome,curso,estado. Estados permitidos: activo ou inactivo.</p></div></div>
 <form class="form-stack" method="post" action="/admin/estudantes/previsualizar" enctype="multipart/form-data">${csrfField(csrf)}<label>Ficheiro CSV (até 1 MB)<input type="file" name="ficheiro" accept=".csv,text/csv" required></label><button class="btn btn-primary">Pré-visualizar</button></form></section>
 ${preview?`<section class="panel form-panel"><h2>Pré-visualização</h2><p>${preview.rows.length} registos válidos; ${preview.errors.length} erros.</p>${preview.errors.map(error=>`<p class="form-error">${e(error)}</p>`).join('')}${preview.rows.length?administrationTable(['NÚMERO','NOME','CURSO','ESTADO'],preview.rows.slice(0,60).map(r=>`<tr><td>${e(r.number)}</td><td>${e(r.name)}</td><td>${e(r.course)}</td><td>${e(r.status)}</td></tr>`)):''}${preview.errors.length===0?`<form method="post" action="/admin/estudantes/importar">${csrfField(csrf)}<textarea name="csv" hidden>${e(preview.text)}</textarea><button class="btn btn-primary">Confirmar importação</button></form>`:''}</section>`:''}
 <section class="panel"><div class="panel-head"><h2>Lista de estudantes</h2></div><form class="filter-bar"><input type="search" name="pesquisa" value="${e(query)}" placeholder="Nome ou número de estudante"><button class="btn btn-subtle">Pesquisar</button></form>${table}</section>`;
}
function documentVersionsPage({document,versions}){
 return `<section class="panel"><div class="panel-head"><div><h2>${e(document.title)}</h2><p>Histórico de ficheiros publicados.</p></div><a class="btn btn-subtle" href="/documentos">Voltar</a></div>${administrationTable(['VERSÃO','FICHEIRO','DATA','AUTOR','NOTA','ACÇÃO'],versions.map(v=>`<tr><td>${v.version}</td><td>${e(v.original_name)}</td><td>${niceDate(v.created_at)}</td><td>${e(v.uploaded_name||'Utilizador removido')}</td><td>${e(v.note||'')}</td><td><a class="btn btn-subtle" href="/documentos/${document.id}/versoes/${v.version}/descarregar">Descarregar</a></td></tr>`))}</section>`;
}
function assignmentPanel({ticket,staffMembers,csrf,canAssign,slaHours}){
 const until=new Date(Date.parse(ticket.created_at.replace(' ','T')+'Z')+slaHours*3600000);
 return `<section class="panel form-panel"><div class="panel-head"><h2>Responsável pelo atendimento</h2></div><p>Prazo de referência: ${slaHours} horas desde a abertura (${until.toLocaleString('pt-MZ',{timeZone:'Africa/Maputo'})}).</p><p>Responsável actual: <strong>${e(staffMembers.find(s=>s.id===ticket.assigned_to)?.name||'Sem responsável')}</strong></p>
 <form method="post" action="/pedidos/${ticket.id}/assumir">${csrfField(csrf)}<button class="btn btn-primary" type="submit">Assumir pedido</button></form>
 ${canAssign?`<form method="post" action="/pedidos/${ticket.id}/atribuir" class="form-stack">${csrfField(csrf)}<label>Atribuir a um funcionário<select name="assigned_to"><option value="">Sem responsável</option>${staffMembers.map(u=>`<option value="${u.id}" ${ticket.assigned_to===u.id?'selected':''}>${e(u.name)}</option>`).join('')}</select></label><button class="btn btn-subtle" type="submit">Guardar responsável</button></form>`:''}</section>`;
}

function recoveryRequestPage(csrf,message=''){
 return publicLayout('Recuperar acesso',`<main class="auth-card" style="margin:3rem auto"><h1>Recuperar palavra-passe</h1><p>Introduza o email associado à sua conta.</p>${message?`<div class="notice">${e(message)}</div>`:''}<form method="post" action="/recuperar" class="form-stack">${csrfField(csrf)}<label>Email<input name="email" type="email" required autocomplete="email"></label><button class="btn btn-primary">Enviar instruções</button></form><p><a href="/entrar">Voltar ao início de sessão</a></p></main>`);
}
function recoveryPasswordPage(csrf,token){
 return publicLayout('Definir nova palavra-passe',`<main class="auth-card" style="margin:3rem auto"><h1>Nova palavra-passe</h1><form method="post" action="/recuperar/${e(token)}" class="form-stack">${csrfField(csrf)}<label>Nova palavra-passe<input name="password" type="password" required minlength="10" autocomplete="new-password"></label><p class="hint">Pelo menos 10 caracteres, incluindo maiúsculas, minúsculas e números.</p><button class="btn btn-primary">Guardar palavra-passe</button></form></main>`);
}
function verificationPage(csrf,token){
 return publicLayout('Confirmar email',`<main class="auth-card" style="margin:3rem auto"><h1>Confirmar email</h1><p>Confirme que pretende validar o endereço de email associado à sua conta.</p><form method="post" action="/verificar/${e(token)}">${csrfField(csrf)}<button class="btn btn-primary">Confirmar email</button></form></main>`);
}
function notificationPreferences({user,csrf}){
 return `<section class="panel form-panel"><div class="panel-head"><h2>Preferências</h2></div><form method="post" action="/perfil/notificacoes" class="form-stack">${csrfField(csrf)}<label><input type="checkbox" name="notify_email" value="1" ${user.notify_email?'checked':''}> Receber notificações por email</label><label><input type="checkbox" name="notify_sms" value="1" ${user.notify_sms?'checked':''}> Receber notificações por SMS (quando disponível)</label><p class="hint">Os envios dependem da configuração institucional. As notificações dentro da aplicação continuam disponíveis.</p><button class="btn btn-primary">Guardar preferências</button></form><a href="/perfil">Voltar ao perfil</a></section>`;
}
function mailQueuePage({items,csrf}){
 return `<section class="panel"><div class="panel-head"><h2>Fila de envios</h2><p>Os envios requerem SMTP ou webhook configurado no servidor.</p></div>${administrationTable(['ID','CANAL','DESTINO','ASSUNTO','ESTADO','TENTATIVAS','ACÇÃO'],items.map(x=>`<tr><td>${x.id}</td><td>${e(x.channel)}</td><td>${e(x.recipient)}</td><td>${e(x.subject)}</td><td>${e(x.status)}${x.last_error?`<small>${e(x.last_error)}</small>`:''}</td><td>${x.attempts}</td><td><form method="post" action="/admin/notificacoes/${x.id}/reenviar">${csrfField(csrf)}<button class="btn btn-small btn-subtle" type="submit">Reenviar</button></form></td></tr>`))}</section>`;
}

function institutionPage(){
 const source=(href,label)=>`<a href="${e(href)}" target="_blank" rel="noopener noreferrer">${e(label)}</a>`;
 return `<section class="institution-page">
 <div class="institution-hero"><span class="kicker">INFORMAÇÃO INSTITUCIONAL</span><h1>${e(I.name)}</h1><p class="institution-motto">${e(I.motto)}</p><p>Informações públicas recolhidas do sítio oficial do ISMMA. Este portal é um projecto demonstrativo e não substitui os canais oficiais da instituição.</p></div>
 <div class="institution-columns"><section class="panel institution-panel"><h2>Contacto e localização</h2><dl>
 <dt>Morada</dt><dd>${e(I.address)}</dd><dt>Telefone</dt><dd><a href="tel:+258826253616">${e(I.phone)}</a></dd>
 <dt>Email</dt><dd><a href="mailto:${e(I.email)}">${e(I.email)}</a></dd><dt>Horário de atendimento publicado</dt><dd>${e(I.hours)}</dd><dt>Fundação</dt><dd>${e(I.founded)}</dd></dl>
 <p class="source-note">Fonte: ${source(I.sources.contacts,'Contactos')} e ${source(I.sources.history,'História')} do ISMMA.</p></section>
 <section class="panel institution-panel"><h2>Missão e visão</h2><h3>Missão</h3><p>${e(I.mission)}</p><h3>Visão</h3><p>${e(I.vision)}</p><p class="source-note">Resumo a partir da página ${source(I.sources.mission,'Missão, Visão e Objectivos')}.</p></section></div>
 <section id="cursos" class="panel institution-panel"><h2>Licenciaturas publicadas</h2><p>Exemplos de cursos publicados pelo ISMMA; confirme sempre a oferta e as condições de admissão mais recentes no sítio oficial.</p><ul class="institution-courses">${I.courses.map(course=>`<li>${e(course)}</li>`).join('')}</ul><p class="source-note">Fonte: ${source(I.sources.courses,'Página de Licenciaturas do ISMMA')}.</p></section>
 <div class="institution-actions"><a class="btn btn-primary" href="/registar">Criar conta de demonstração</a>${source(I.website,'Visitar o site oficial do ISMMA')}</div></section>`;
}
module.exports={STATUS,PRIORITY,ROLE,VISIBILITY,e,niceDate,icon,statusBadge,priorityBadge,csrfField,layout,publicLayout,landing,institutionPage,authForm,dashboard,ticketList,newTicket,ticketDetail,documentPage,notificationPage,profile,usersAdmin,userEdit,departmentsAdmin,categoriesAdmin,templatesPage,settingsAdmin,reportsPage,auditPage,errorPage,studentRosterPage,documentVersionsPage,assignmentPanel,recoveryRequestPage,recoveryPasswordPage,verificationPage,notificationPreferences,mailQueuePage};
